import { GoogleGenAI, Type } from "@google/genai";

// Initialize Gemini Client
// NOTE: Ensure your VITE_API_KEY or API_KEY is set in your environment variables.
const apiKey = process.env.API_KEY || ''; 
const ai = new GoogleGenAI({ apiKey });

interface SeoContent {
    title: string;
    description: string;
}

interface BlogPostData {
    title: string;
    excerpt: string;
    content: string; // HTML
    imagePrompt: string;
    category: string;
}

// Fallback Mock Data
const mockSeoData: Record<string, SeoContent> = {
    Home: {
        title: "Sameer Digital Lab - Web & Mobile App Development Agency",
        description: "Professional web & mobile app development agency. We build custom websites, React Native apps, WordPress solutions. Affordable prices, fast delivery.",
    },
    // ... (Keep existing mock data keys if needed for fallback)
};

export const generateSeoContent = async (pageName: string): Promise<SeoContent> => {
    // Return mock data immediately if no key is present to prevent crashes during dev without key
    if (!apiKey) {
        console.warn("Gemini API Key missing. Using mock SEO data.");
        return new Promise((resolve) => {
            setTimeout(() => {
                resolve({ 
                    title: `Sameer Digital Lab | ${pageName}`, 
                    description: `Premium digital services for ${pageName}. Web development, mobile apps, and SEO.` 
                });
            }, 500);
        });
    }

    try {
        const prompt = `Generate a premium, SEO-friendly meta title (max 60 chars) and meta description (max 160 chars) for the '${pageName}' page of a futuristic, high-end digital agency called 'Sameer Digital Lab'. The tone should be professional, innovative, and authoritative.`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: { type: Type.STRING },
                        description: { type: Type.STRING },
                    },
                    required: ['title', 'description'],
                },
            }
        });

        if (response.text) {
            return JSON.parse(response.text);
        }
        throw new Error("No response from AI");

    } catch (error) {
        console.error("SEO Gen Error:", error);
        return { 
            title: `Sameer Digital Lab | ${pageName}`, 
            description: `Leading digital agency for ${pageName}.` 
        };
    }
};

/**
 * Generates a full blog post including HTML content and an image prompt.
 */
export const generateBlogPost = async (topic?: string, category: string = "Technology"): Promise<BlogPostData> => {
    if (!apiKey) {
        alert("API Key is missing! Please check services/geminiService.ts");
        throw new Error("API Key Missing");
    }

    const userTopic = topic || "The latest trends in Web Development and AI for Business Growth";

    const prompt = `
        You are a senior content writer for 'Sameer Digital Lab', a premium web and mobile app development agency.
        Write a high-quality, SEO-optimized blog post about: "${userTopic}".
        Category context: ${category}.

        Requirements:
        1. Title: Catchy, professional, and SEO-optimized.
        2. Excerpt: A compelling summary (2 sentences).
        3. Content: detailed, educational, and professional. Use HTML formatting (<h2>, <p>, <ul>, <li>, <strong>). Do NOT use <h1> or <html> tags. Include 3 key takeaways.
        4. ImagePrompt: A detailed, artistic text description to generate a futuristic, cinematic, high-definition 4k wallpaper-style image representing this blog topic. (e.g. "Cyberpunk city with neon code, 4k, cinematic lighting").

        Return JSON format.
    `;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: { type: Type.STRING },
                        excerpt: { type: Type.STRING },
                        content: { type: Type.STRING },
                        imagePrompt: { type: Type.STRING },
                        category: { type: Type.STRING }
                    },
                    required: ['title', 'excerpt', 'content', 'imagePrompt', 'category'],
                },
            }
        });

        if (response.text) {
            return JSON.parse(response.text);
        }
        throw new Error("Empty response from Gemini");

    } catch (error) {
        console.error("Blog Gen Error:", error);
        throw error;
    }
};

import React, { useState, useEffect } from 'react';
import { supabase } from '../../services/supabaseClient';
import { generateBlogPost } from '../../services/geminiService';
import { motion, AnimatePresence } from 'framer-motion';
import PremiumButton from '../../components/PremiumButton';
import { LightbulbIcon, StarIcon, LoaderIcon } from '../../components/Icons';

interface Blog {
    id: number;
    title: string;
    category: string;
    image: string;
    date: string;
    excerpt: string;
    content: string;
}

// Random topics to simulate "Daily" automation if user leaves topic empty
const randomTopics = [
    "The Future of AI in Web Design",
    "Why React Native is Best for Mobile Apps",
    "How to Optimize Shopify Stores for Sales",
    "SEO Strategies for 2025",
    "The Importance of UI/UX in SaaS Products",
    "Headless CMS vs Traditional WordPress",
    "Cybersecurity Tips for Modern Websites"
];

const ManageBlogs: React.FC = () => {
    const [blogs, setBlogs] = useState<Blog[]>([]);
    const [loading, setLoading] = useState(true);
    const [isEditing, setIsEditing] = useState(false);

    // AI State
    const [isGenerating, setIsGenerating] = useState(false);
    const [aiTopic, setAiTopic] = useState('');

    // Form State
    const [currentBlog, setCurrentBlog] = useState<Partial<Blog>>({
        title: '',
        category: 'Technology',
        image: '',
        date: '',
        excerpt: '',
        content: ''
    });

    useEffect(() => {
        fetchBlogs();
    }, []);

    const fetchBlogs = async () => {
        setLoading(true);
        const { data, error } = await supabase.from('blogs').select('*').order('created_at', { ascending: false });
        if (error) console.error('Error fetching blogs:', error);
        else setBlogs(data || []);
        setLoading(false);
    };

    const handleSave = async () => {
        // Auto-fill date if missing
        const blogData = {
            ...currentBlog,
            date: currentBlog.date || new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
        };

        if (currentBlog.id) {
            const { error } = await supabase.from('blogs').update(blogData).eq('id', currentBlog.id);
            if (error) alert('Error updating blog');
        } else {
            const { error } = await supabase.from('blogs').insert([blogData]);
            if (error) alert('Error creating blog');
        }

        setIsEditing(false);
        fetchBlogs();
        resetForm();
    };

    const handleDelete = async (id: number) => {
        if (!window.confirm('Delete this post?')) return;
        const { error } = await supabase.from('blogs').delete().eq('id', id);
        if (error) alert('Error deleting blog');
        else fetchBlogs();
    };

    const handleAIGenerate = async () => {
        setIsGenerating(true);
        try {
            // 1. Pick topic (User input OR Random)
            const topic = aiTopic || randomTopics[Math.floor(Math.random() * randomTopics.length)];

            // 2. Call Gemini for Text
            const aiData = await generateBlogPost(topic, currentBlog.category || 'Technology');

            // 3. Generate Image URL using Pollinations.ai (Free, Fast, No Key needed)
            // We use the 'imagePrompt' from Gemini to get a specific visual
            const encodedPrompt = encodeURIComponent(aiData.imagePrompt + " high quality, 4k, trending on artstation, futuristic, sleek");
            const aiImageUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=1200&height=800&nologo=true&seed=${Math.floor(Math.random() * 1000)}`;

            // 4. Update Form
            setCurrentBlog({
                ...currentBlog,
                title: aiData.title,
                excerpt: aiData.excerpt,
                content: aiData.content,
                category: aiData.category,
                image: aiImageUrl,
                date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
            });

        } catch (error) {
            console.error(error);
            alert("Failed to generate blog. Check API Key configuration.");
        } finally {
            setIsGenerating(false);
        }
    };

    const resetForm = () => {
        setCurrentBlog({ category: 'Technology' });
        setAiTopic('');
    };

    const openEdit = (blog: Blog) => {
        setCurrentBlog(blog);
        setIsEditing(true);
    };

    const openNew = () => {
        resetForm();
        setIsEditing(true);
    };

    if (isEditing) {
        return (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                    <h3 className="text-xl font-bold text-white">{currentBlog.id ? 'Edit Post' : 'New Post'}</h3>

                    {/* AI Generator Controls */}
                    {!currentBlog.id && (
                        <div className="flex items-center gap-2 bg-slate-950 border border-purple-500/30 p-2 rounded-xl">
                            <input 
                                type="text" 
                                placeholder="Topic (Optional)" 
                                value={aiTopic}
                                onChange={(e) => setAiTopic(e.target.value)}
                                className="bg-transparent text-white text-sm px-2 focus:outline-none w-40"
                            />
                            <button 
                                onClick={handleAIGenerate}
                                disabled={isGenerating}
                                className="flex items-center gap-2 bg-gradient-to-r from-purple-600 to-blue-600 hover:from-purple-500 hover:to-blue-500 text-white px-4 py-2 rounded-lg text-sm font-bold transition-all disabled:opacity-50"
                            >
                                {isGenerating ? (
                                    <>
                                        <LoaderIcon className="w-4 h-4 animate-spin" /> Generating...
                                    </>
                                ) : (
                                    <>
                                        <StarIcon className="w-4 h-4" /> Auto-Generate
                                    </>
                                )}
                            </button>
                        </div>
                    )}

                    <button onClick={() => setIsEditing(false)} className="text-slate-400 hover:text-white text-sm">Cancel</button>
                </div>

                <div className="space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-4">
                            <label className="text-xs font-bold text-slate-500 uppercase">Blog Title</label>
                            <input 
                                placeholder="Title" 
                                value={currentBlog.title || ''} 
                                onChange={e => setCurrentBlog({...currentBlog, title: e.target.value})} 
                                className="w-full bg-slate-950 border border-slate-800 p-3 rounded-lg text-white focus:border-cyan-500 outline-none" 
                            />
                        </div>
                        <div className="space-y-4">
                            <label className="text-xs font-bold text-slate-500 uppercase">Category</label>
                            <input 
                                placeholder="Technology, Design, Business..." 
                                value={currentBlog.category || ''} 
                                onChange={e => setCurrentBlog({...currentBlog, category: e.target.value})} 
                                className="w-full bg-slate-950 border border-slate-800 p-3 rounded-lg text-white focus:border-cyan-500 outline-none" 
                            />
                        </div>
                    </div>

                    {/* Image Preview & Input */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-xs font-bold text-slate-500 uppercase">Cover Image URL</label>
                            <div className="flex gap-2">
                                <input 
                                    placeholder="https://..." 
                                    value={currentBlog.image || ''} 
                                    onChange={e => setCurrentBlog({...currentBlog, image: e.target.value})} 
                                    className="w-full bg-slate-950 border border-slate-800 p-3 rounded-lg text-white focus:border-cyan-500 outline-none" 
                                />
                            </div>
                            <p className="text-[10px] text-slate-500">AI automatically generates a unique image here.</p>
                        </div>
                        <div className="relative h-32 bg-slate-950 border border-slate-800 rounded-lg overflow-hidden flex items-center justify-center">
                            {currentBlog.image ? (
                                <img src={currentBlog.image} alt="Preview" className="w-full h-full object-cover" />
                            ) : (
                                <span className="text-slate-600 text-xs">Image Preview</span>
                            )}
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-xs font-bold text-slate-500 uppercase">Short Excerpt</label>
                        <textarea 
                            placeholder="Brief summary for the card..." 
                            rows={3} 
                            value={currentBlog.excerpt || ''} 
                            onChange={e => setCurrentBlog({...currentBlog, excerpt: e.target.value})} 
                            className="w-full bg-slate-950 border border-slate-800 p-3 rounded-lg text-white focus:border-cyan-500 outline-none" 
                        />
                    </div>

                    <div className="space-y-2">
                        <label className="text-xs font-bold text-slate-500 uppercase">Full Content (HTML Supported)</label>
                        <textarea 
                            placeholder="<p>Write your blog content here...</p>" 
                            rows={15} 
                            value={currentBlog.content || ''} 
                            onChange={e => setCurrentBlog({...currentBlog, content: e.target.value})} 
                            className="w-full bg-slate-950 border border-slate-800 p-3 rounded-lg text-white font-mono text-sm focus:border-cyan-500 outline-none" 
                        />
                    </div>
                </div>

                <div className="mt-8 flex justify-end gap-4">
                    <button onClick={() => setIsEditing(false)} className="px-6 py-3 text-slate-400 hover:text-white transition-colors">Discard</button>
                    <PremiumButton onClick={handleSave} icon={false} className="!px-8 !py-3">Save & Publish</PremiumButton>
                </div>
            </motion.div>
        );
    }

