             setCampaigns(prev => [{ ...newCampaign, id: Math.random(), status: newCampaign.status as any }, ...prev]);
        } else {
            fetchHistory();
        }

        setIsSending(false);
        setSendingProgress('');
        alert(count > 0 ? `Successfully sent to ${count} recipients!` : 'Failed to send. Check console.');
        if (count > 0) {
            setRecipients('');
            setSubject('');
            setBody('');
        }
