        // Safe Parse ID
        const blogId = id ? parseInt(id, 10) : 6; 

        if (isNaN(blogId)) return;

        const { data, error } = await supabase
            .from('comments')
            .select('*')
            .eq('blog_id', blogId)
            .order('created_at', { ascending: false });

        if (data) setExistingComments(data);
