interface TocItem {
    id: string;
    text: string;
    level: string; // 'h2' or 'h3'
}

const BlogPostPage: React.FC = () => {
    const { id } = useParams();
    const { scrollYProgress } = useScroll();
    const scaleX = useSpring(scrollYProgress, {
        stiffness: 100,
        damping: 30,
        restDelta: 0.001
    });

    // TOC State
    const [processedContent, setProcessedContent] = useState('');
    const [tocItems, setTocItems] = useState<TocItem[]>([]);
    const [activeId, setActiveId] = useState<string>('');

    // Observer Refs
    const observer = useRef<IntersectionObserver | null>(null);
    const contentRef = useRef<HTMLDivElement>(null);

    // 1. Process Content on Load (Generate IDs and TOC)
    useEffect(() => {
        const processHtml = () => {
            const parser = new DOMParser();
            const doc = parser.parseFromString(blogData.content, 'text/html');
            const headings = doc.querySelectorAll('h2, h3');
            const newToc: TocItem[] = [];

            headings.forEach((heading, index) => {
                const text = heading.textContent || '';
                // Create a slug ID: "My Title" -> "my-title"
                const slug = text.toLowerCase()
                    .replace(/[^a-z0-9]+/g, '-')
                    .replace(/(^-|-$)+/g, '');

                const uniqueId = `${slug}-${index}`; // Ensure uniqueness with index
                heading.id = uniqueId;

                newToc.push({
                    id: uniqueId,
                    text: text,
                    level: heading.tagName.toLowerCase()
                });
            });

            setProcessedContent(doc.body.innerHTML);
            setTocItems(newToc);
        };

        processHtml();
    }, [blogData.content]);

    // 2. Set up Intersection Observer for Active State
    useEffect(() => {
        if (!processedContent) return;

        const handleObserver = (entries: IntersectionObserverEntry[]) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    setActiveId(entry.target.id);
                }
            });
        };

        observer.current = new IntersectionObserver(handleObserver, {
            rootMargin: "-20% 0px -50% 0px", // Trigger when element is near top/center
            threshold: 0.1
        });

        // Small timeout to wait for React to render the dangerouslySetInnerHTML
        setTimeout(() => {
            const headings = contentRef.current?.querySelectorAll('h2, h3');
            headings?.forEach((heading) => observer.current?.observe(heading));
        }, 100);

        return () => observer.current?.disconnect();
    }, [processedContent]);

    // Comment State
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [website, setWebsite] = useState('');
    const [comment, setComment] = useState('');
    const [submitting, setSubmitting] = useState(false);
    const [existingComments, setExistingComments] = useState<any[]>([]);

    useEffect(() => {
        fetchComments();
    }, [id]);

    const fetchComments = async () => {
        // Safe Parse ID
        const blogId = id ? parseInt(id, 10) : 6; 

        if (isNaN(blogId)) return;

        const { data, error } = await supabase
            .from('comments')
            .select('*')
            .eq('blog_id', blogId)
            .order('created_at', { ascending: false });

        if (data) setExistingComments(data);
    };

    const handleCommentSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!name || !email || !comment) return alert("Please fill required fields.");

        setSubmitting(true);
        const blogId = id ? parseInt(id, 10) : 6;

        const { error } = await supabase.from('comments').insert([{
            blog_id: blogId,
            name,
            email,
            website,
            content: comment,
            created_at: new Date().toISOString()
        }]);

        if (error) {
            console.error("Supabase Comment Error:", error);
            alert(`Error posting comment: ${error.message || 'Unknown error'}`);
        } else {
            alert('Comment submitted successfully!');
            setName('');
            setEmail('');
            setWebsite('');
            setComment('');
            fetchComments();
        }
        setSubmitting(false);
    };

    const handleShare = (platform: string) => {
        const url = window.location.href;
        const text = `Check out this article by Sameer Digital Lab: ${blogData.title}`;

        switch(platform) {
            case 'twitter':
                window.open(`https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`, '_blank');
                break;
            case 'linkedin':
                window.open(`https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(url)}`, '_blank');
                break;
            case 'facebook':
                window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`, '_blank');
                break;
            case 'copy':
                navigator.clipboard.writeText(url);
                alert('Link copied to clipboard!');
                break;
        }
    };

