                                    .blog-content h2 { font-family: 'Oswald', sans-serif; font-size: 2rem; font-weight: 700; color: #f8fafc; margin-top: 3rem; margin-bottom: 1.5rem; line-height: 1.2; scroll-margin-top: 100px; }
