                                </div>
                                <h4 className="text-white font-bold text-lg mb-1 line-clamp-1 group-hover:text-cyan-400 transition-colors">{blog.title}</h4>
                                <p className="text-slate-400 text-sm line-clamp-2">{blog.excerpt}</p>
